import React, { useState } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { Helmet } from 'react-helmet-async';
import { Card, Grid, Button, Typography, IconButton, InputAdornment, Box, Switch } from '@mui/material';
// import { toast } from 'react-toastify';
import TextField from '@mui/material/TextField';
import InputLabel from '@mui/material/InputLabel';
import { axios } from '../../utils/axios';
import Iconify from '../../components/iconify';
import { useMyContext } from '../provider';
import GenerateToastConfig from '../../components/toast-config/GenerateToastConfig';
import GoBackButton from '../../components/goBackButton/GoBackButton';
import InputField from '../../components/input/inputField';
import useResponsive from '../../hooks/useResponsive';

export default function AddaminPage() {
  const navigate = useNavigate();
  const location = useLocation();
  const [amenityCategory, setAmenityCategory] = useState('');
  const [decscribe, setDecscribe] = useState('');
  const [iconFile, setIconFile] = useState(null);
  const [iconpreview, setIconpreview] = useState(null);
  const [imageFile, setImageFile] = useState(null);
  const [imagepreview, setImagepreview] = useState(null);
  const { i18 } = useMyContext();
  const isMobile = useResponsive('down', 'sm')
  const [allCategoryToggle, setAllCategoryToggle] = useState(false)

  if (!location?.state)
    return null

  const isAddButtonDisabled = !amenityCategory || !decscribe || !iconFile;
  const isAddButtondisabled = !amenityCategory || !decscribe;
  const isAddButtondisable = !amenityCategory || !iconFile;
  const { types, process, ids, categories, isAll, module } = location?.state || { types: '', process: '', ids: '', categories: '', module };

  const backtouser = () => {
    if (types === 'Amenity Category') {
      navigate('/dashboard/amenityCategory');
    } else if (types === 'Category') {
      navigate('/dashboard/category');
    } else if (types === 'Amenity Data') {
      navigate(`/dashboard/amenitydata?id=${ids}`, { state: { cate: categories, catid: ids } });
    } else if (types === "Property" && module !== "listing") {
      navigate(`/dashboard/property?id=${ids}`, { state: { cate: categories, catids: ids } });
    } else {
      navigate(-1);
    }
  };

  const handleIconChange = (e) => {
    const file = e.target.files[0];
    const reader = new FileReader();

    reader.onloadend = () => {
      setIconpreview(reader.result);
      setIconFile(file);
    };

    if (file) {
      reader.readAsDataURL(file);
    }
  };

  const handleImageChange = (e) => {
    const file = e.target.files[0];
    const reader = new FileReader();

    reader.onloadend = () => {
      setImagepreview(reader.result);
      setImageFile(file);
    };

    if (file) {
      reader.readAsDataURL(file);
    }
  };

  const AddAmenityCategory = async () => {
    try {
      const formData = new FormData();
      formData.append('name', amenityCategory);
      formData.append('desc', decscribe);
      formData.append('icon', iconFile);


      if (types === 'Amenity Category') {
        const res = await axios.post('module/admin/amenityCategory', {
          category: amenityCategory,
          desc: decscribe,
        });
        if (res.status === 200) {
          GenerateToastConfig(res.data.message, 'success');
          navigate('/dashboard/amenityCategory');
        } else {
          GenerateToastConfig(res.data.message);
        }
      } else if (types === 'Amenity Data') {
        const res = await axios.post(`module/admin/amenity/${ids}`, formData);

        if (res.status === 200) {
          GenerateToastConfig(res.data.message, 'success');
          navigate(`/dashboard/amenitydata?id=${ids}`, { state: { categories, catid: ids } });
        } else {
          GenerateToastConfig(res.data.message);
        }
      } else if (types === 'Category') {
        const formData = new FormData();
        formData.append('category', amenityCategory);
        formData.append('isAll', allCategoryToggle)
        if (iconFile)
          formData.append('icon', iconFile);
        if (imageFile)
          formData.append('image', imageFile);

        const res = await axios.post('module/admin/category', formData);
        if (res.status === 200) {
          GenerateToastConfig(res.data.message, 'success');
          navigate('/dashboard/category');
        } else {
          GenerateToastConfig(res.data.message);
        }
      } else if (types === 'Property') {
        const formData = new FormData();
        formData.append('property', amenityCategory);
        formData.append('icon', iconFile);
        formData.append('desc', decscribe)

        const res = await axios.post(`module/admin/property/${ids}`, formData);
        if (res.status === 200) {
          GenerateToastConfig(res.data.message, 'success');
          if(module === "listing") {
            navigate(-1)
          } else {
            navigate(`/dashboard/property?id=${ids}`, { state: { cate: categories, catids: ids } });
          }
        } else {
          GenerateToastConfig(res.data.message);
        }
      }
    } catch (err) {
      GenerateToastConfig(err.message || err?.response?.data?.message);
    }
  };

  const updateAmenityCategory = async (ids) => {
    const token = localStorage.getItem('admintoken');
    const headers = {
      Authorization: `${token}`,
      'Content-Type': 'application/json',
    };
    try {
      const res = await axios.put(`module/admin/amenityCategory/${ids}`, {
        category: categories || amenityCategory,
        desc: decscribe,
      });
      if (res.status === 200) {
        GenerateToastConfig(res.data.message, 'success');
        navigate('/dashboard/amenityCategory', { state: { cate: categories, catids: ids } });
      } else {
        GenerateToastConfig(res.data.message);
      }
    } catch (err) {
      GenerateToastConfig(err?.response?.data?.message);
    }
  };

  const handleAllCategoryToggle = (event) => {
    setAllCategoryToggle(event.target.checked)
  }
  
  return (
    <>
      <Helmet>
        <title>{`${process} ${types}`}</title>
      </Helmet>
      <Card sx={{ padding: '20px 10px', margin: '30px 0px' }}>
        <Grid container sx={{ borderBottom: '1px solid #dbe0e4', padding: '10px 0px' }}>
          <Grid container item justifyContent="space-between" alignItems="center" sx={{ marginRight: '10px' }}>
            <Typography variant="h6" gutterBottom sx={{ margin: '0px 0px 0px 10px', paddingBottom: '0px' }}>
              {types === 'Amenity Category' ?
                i18?.LISTINGPAGE?.ADD_AMENITY_CATEGORY || "Add Amenity Category" :
                types === 'Category' ?
                  i18?.LISTINGPAGE?.MAIN_CATEGORY || 'Main Category' :
                  types === 'Amenity Data' ?
                    i18?.LISTINGPAGE?.AMENITY_DATA || 'Amenity Data' :
                    i18?.LISTINGPAGE?.CATEGORY || 'Category'
              }
            </Typography>
            {/* <Button variant="contained" onClick={backtouser} startIcon={<Iconify icon="icon-park-twotone:back" />}>
              {i18?.LISTINGPAGE?.GO_BACK || "Go Back"}
            </Button> */}
            <GoBackButton
              label={i18?.LISTINGPAGE?.GO_BACK || "Go Back"}
              onClick={backtouser}
              icon="icon-park-twotone:back"
            // i18={i18} 
            />
          </Grid>
        </Grid>
        {process === 'Add' && types === 'Amenity Category' && (
          <Grid container={!isMobile} sx={{ marginTop: '10px' }}>
            <Grid item xs={6} sx={{ padding: '0px 5px' }}>
              <InputField
                value={amenityCategory}
                name="FirstName"
                label={i18?.LISTINGPAGE?.AMENITY_CATEGORY || "Amenity Category"}
                sx={{ margin: '10px 0px', width: '100%' }}
                onChange={(e) => setAmenityCategory(e.target.value)}
              />
            </Grid>

            <Grid item xs={6} sx={{ padding: '0px 5px' }}>
              <InputField
                value={decscribe}
                name="LastName"
                label={i18?.LISTINGPAGE?.AMENITY_DESCRIPTION || "Amenity Description"}
                sx={{ margin: '10px 0px', width: '100%' }}
                onChange={(e) => setDecscribe(e.target.value)}
              />
            </Grid>
          </Grid>
        )}

        {process === 'Add' && types === 'Amenity Data' && (
          <Grid container={!isMobile} sx={{ marginTop: '10px' }}>
            <Grid item xs={6} sx={{ padding: '0px 5px' }}>
              <InputField
                value={amenityCategory}
                name="FirstName"
                label={i18?.LISTINGPAGE?.AMENITY_NAME || "Amenity Name"}
                sx={{ margin: '10px 0px', width: '100%' }}
                onChange={(e) => setAmenityCategory(e.target.value)}
              />
            </Grid>

            <Grid item xs={6} sx={{ padding: '0px 5px' }}>
              <InputField
                value={decscribe}
                name="LastName"
                label={i18?.LISTINGPAGE?.AMENITY_DESCRIPTION || "Amenity Description"}
                sx={{ margin: '10px 0px', width: '100%' }}
                onChange={(e) => setDecscribe(e.target.value)}
              />
            </Grid>
            <Grid container justifyContent="flex-start" alignItems="center" sx={{ marginTop: '10px', padding: '0px 5px' }}>
              <InputLabel
                id="demo-simple-select-label"
                style={{
                  cursor: 'pointer',
                  border: '1px solid #adb5bd',
                  borderRadius: '5px',
                  padding: '15px',
                  width: isMobile ? '100%' : '50%',
                }}
              >
                <input
                  type="file"
                  id="image-upload"
                  style={{ display: 'none' }}
                  onChange={(e) => handleIconChange(e)}
                />
                <span style={{ color: 'black' }}>{i18?.LISTINGPAGE?.UPLOAD_IMAGE || "Upload Image"}</span>
                {iconpreview && (
                  <img
                    src={iconpreview}
                    alt="Preview"
                    style={{ maxWidth: '50px', width: '100%', marginTop: '8px' }}
                  />
                )}
              </InputLabel>
            </Grid>
          </Grid>
        )}

        {process === 'Add' && types === 'Category' && (
          <>
            <Grid container={!isMobile} sx={{ marginTop: '10px', padding: '0px 5px' }}>
              <Grid item xs={ !isAll ? 6 : 12} sx={!isAll && { padding: !isMobile  ? '0px 10px 0px 0px' : '0px 0px 10px 0px' }}>
                <InputField
                  value={amenityCategory}
                  name="FirstName"
                  label={i18?.LISTINGPAGE?.MAIN_CATEGORY || "Main Category"}
                  sx={{ margin: '10px 0px', width: '100%' }}
                  onChange={(e) => setAmenityCategory(e.target.value)} />
              </Grid>
              {!isAll && <Grid item xs={6} >
                <InputLabel>{i18?.LISTINGPAGE?.ALL_CATEGORY || "All Category"}</InputLabel>
                <Box
                  sx={{
                    border: '1px solid #ccc',
                    borderRadius: '4px',
                    padding: '8px',
                    margin: '10px 0',
                    display: 'flex',
                    justifyContent: 'space-between',
                    alignItems: 'center',
                  }}
                >
                  <Typography>{i18?.LISTINGPAGE?.ALL_CATEGORY || "All Category"}</Typography>
                  <Switch
                    checked={allCategoryToggle}
                    onChange={handleAllCategoryToggle}
                    color='primary'
                  />
                </Box>
              </Grid>}
            </Grid>
            <Grid container={!isMobile} sx={{ padding: '0px 5px' }}>
              <Grid item xs={6} sx={{ padding: !isMobile ? '0px 10px 0px 0px' : '0px 0px 10px 0px'}}>
                <InputLabel
                  id="demo-simple-select-label"
                  position={'absolute'}
                  sx={{
                    cursor: 'pointer',
                    border: '1px solid #adb5bd',
                    borderRadius: '5px',
                    padding: '15px',
                    width: '100%',
                  }}
                >
                  <input
                    type="file"
                    id="image-upload"
                    style={{ display: 'none' }}
                    onChange={(e) => handleIconChange(e)} />
                  <span style={{ color: 'black' }}>{i18?.LISTINGPAGE?.UPLOAD_ICON || "Upload Icon"}</span>
                  {iconpreview && (
                    <img
                      src={iconpreview}
                      alt="Preview"
                      style={{ maxWidth: '50px', width: '100%', marginTop: '8px' }} />
                  )}
                </InputLabel>
              </Grid>
              <Grid item xs={6}>
                <InputLabel
                  id="demo-simple-select-label"
                  position={'absolute'}
                  sx={{
                    cursor: 'pointer',
                    border: '1px solid #adb5bd',
                    borderRadius: '5px',
                    padding: '15px',
                    width: '100%',
                  }}
                >
                  <input
                    type="file"
                    id="image-upload"
                    accept="image/*"
                    style={{ display: 'none' }}
                    onChange={(e) => handleImageChange(e)} />
                  <span style={{ color: 'black' }}>{i18?.LISTINGPAGE?.UPLOAD_IMAGE || "Upload Image"}</span>
                  {imagepreview && (
                    <img
                      src={imagepreview}
                      alt="Preview"
                      style={{ maxWidth: '50px', width: '100%', marginTop: '8px' }} />
                  )}
                </InputLabel>
              </Grid>
            </Grid>
          </>
        )}

        {process === 'Add' && types === 'Property' && (
          <Grid container={!isMobile} sx={{ marginTop: '10px' }}>
            <Grid item xs={6} sx={{ padding: '0px 5px' }}>
              <InputField
                value={amenityCategory}
                name="FirstName"
                label={i18?.LISTINGPAGE?.PROPERTY_NAME || "Property Name"}
                sx={{ margin: '10px 0px', width: '100%' }}
                onChange={(e) => setAmenityCategory(e.target.value)}
              />
            </Grid>
            <Grid item xs={6} sx={{ padding: '0px 5px' }}>
              <InputField
                value={decscribe}
                name="LastName"
                label={i18?.LISTINGPAGE?.PROPERTY_DESCRIPTION || "Property Description"}
                sx={{ margin: '10px 0px', width: '100%' }}
                onChange={(e) => setDecscribe(e.target.value)}
              />
            </Grid>
            <Grid container justifyContent="flex-start" alignItems="center" sx={{ marginTop: '10px', padding: '0px 5px' }}>
              <InputLabel
                id="demo-simple-select-label"
                sx={{
                  cursor: 'pointer',
                  border: '1px solid #adb5bd',
                  borderRadius: '5px',
                  padding: '15px',
                  width: isMobile ? '100%' : '50%',
                }}
              >
                <input
                  type="file"
                  id="image-upload"
                  style={{ display: 'none' }}
                  onChange={(e) => handleIconChange(e)}
                />
                <span style={{ color: 'black' }}>{i18?.LISTINGPAGE?.UPLOAD_IMAGE || "Upload Image"}</span>
                {iconpreview && (
                  <img
                    src={iconpreview}
                    alt="Preview"
                    style={{ maxWidth: '50px', width: '100%', marginTop: '8px' }}
                  />
                )}
              </InputLabel>
            </Grid>
          </Grid>
        )}
        <Grid container justifyContent="flex-end" sx={{ marginTop: '10px', padding: '0px 5px' }}>
          {process === 'Add' && (
            <div>
              {types === 'Amenity Data' ? (
                <Button variant="contained" disabled={isAddButtonDisabled} onClick={() => AddAmenityCategory()}>
                  {i18?.LISTINGPAGE?.ADD || "Add"}
                </Button>
              ) : types === 'Category' || types === 'Property' ? (
                <Button variant="contained" disabled={isAddButtondisable} onClick={() => AddAmenityCategory()}>
                  {i18?.LISTINGPAGE?.ADD || "Add"}
                </Button>
              ) : (
                <Button variant="contained" disabled={isAddButtondisabled} onClick={() => AddAmenityCategory()}>
                  {i18?.LISTINGPAGE?.ADD || "Add"}
                </Button>
              )}
            </div>
          )}
          {process === 'Edit' && (
            <Button variant="contained" onClick={() => updateAmenityCategory(ids)}>
              {i18?.LISTINGPAGE?.UPDATE || "Update"}
            </Button>
          )}
        </Grid>
      </Card>
    </>
  );
}
