import { toast } from 'react-toastify';

let lastToastId = null;

const GenerateToastConfig = (message, type = 'error') => {
    message= message || "Server Error"
    const pascalCaseMessage = message
        .replace(/_/g, ' ')
        .split(' ')
        .map(word => word.charAt(0).toUpperCase() + word.slice(1).toLowerCase())
        .join(' ');

    const toastFunctions = {
        success: toast.success,
        info: toast.info,
        error: toast.error,
    };

    const toastFunction = toastFunctions[type] || toast.error;

    // Check if the same message is already shown
    if (lastToastId !== null) {
        toast.dismiss(lastToastId); // Dismiss the previous toast
    }

    const toastOptions = {
        position: 'top-right',
        autoClose: 3000,
        hideProgressBar: false,
        closeOnClick: true,
        pauseOnHover: true,
        draggable: true,
        progress: undefined,
        theme: 'light',
    };

    lastToastId = toastFunction(pascalCaseMessage, toastOptions);
};

export default GenerateToastConfig;


// Explanation:

// lastToastId: This variable stores the ID of the last shown toast notification.
// toast.dismiss(lastToastId): Dismisses the last shown toast if it exists.
// toastFunction(pascalCaseMessage, toastOptions): Displays the toast with the configured options.
// This approach ensures that if the same message (after formatting to PascalCase) is shown again due to rapid API hits, the previous toast is dismissed before showing the new one.